package locale

func init() {
	Register("User paused the task", "User paused the task")
	Register("The user paused the task through POST /api/tasks/{id}/control with action=pause. This Planner/Worker run was cancelled; running intents return to frontier(open), and will be claimed and restarted from the beginning on resume.", "The user paused the task through POST /api/tasks/{id}/control with action=pause. This Planner/Worker run was cancelled; running intents return to frontier(open), and will be claimed and restarted from the beginning on resume.")
	Register("Orchestrator agent paused the task", "Orchestrator agent paused the task")
	Register("The orchestrator called pause_task. This Planner/Worker run was cancelled; running intents return to frontier(open) and execute again after resume.", "The orchestrator called pause_task. This Planner/Worker run was cancelled; running intents return to frontier(open) and execute again after resume.")
	Register("Task was deleted", "Task was deleted")
	Register("The task is being deleted through DELETE /api/tasks/{id}. The deletion barrier cancelled its active Planner, Worker, and main agent; this run's result will no longer be used.", "The task is being deleted through DELETE /api/tasks/{id}. The deletion barrier cancelled its active Planner, Worker, and main agent; this run's result will no longer be used.")
	Register("Backend restored the task's paused state", "Backend restored the task's paused state")
	Register("At startup, the backend restored the persisted paused state from the database. This run was cancelled; normally no agent is running during restoration.", "At startup, the backend restored the persisted paused state from the database. This run was cancelled; normally no agent is running during restoration.")
	Register("Planner marked task complete", "Planner marked task complete")
	Register("The planner marked the task done after confirming its objectives, then cancelled active workers. Their intents are marked stopped, not failed.", "The planner marked the task done after confirming its objectives, then cancelled active workers. Their intents are marked stopped, not failed.")
	Register("Task wrap-up drain expired", "Task wrap-up drain expired")
	Register("After task timeout, workers were allowed to wrap up, but the 90-second drain grace expired. Hard cancellation marks intents exhausted; facts/assets already saved during wrap-up remain.", "After task timeout, workers were allowed to wrap up, but the 90-second drain grace expired. Hard cancellation marks intents exhausted; facts/assets already saved during wrap-up remain.")
	Register("Planner terminated this intent", "Planner terminated this intent")
	Register("The planner used kill_work to terminate this intent, typically because it drifted or no longer justified further work. It is marked stopped and is not automatically reclaimed.", "The planner used kill_work to terminate this intent, typically because it drifted or no longer justified further work. It is marked stopped and is not automatically reclaimed.")
	Register("User paused this worker intent", "User paused this worker intent")
	Register("The user paused the running worker. This call was cancelled and the intent became paused. Registered intents, facts, findings, and activities remain; resuming restarts execution from the beginning.", "The user paused the running worker. This call was cancelled and the intent became paused. Registered intents, facts, findings, and activities remain; resuming restarts execution from the beginning.")
	Register("User deleted this worker intent", "User deleted this worker intent")
	Register("The user deleted the running worker. This call was cancelled. After the worker leaves the write section, soft deletion marks the intent deleted and retains outputs; hard deletion removes it and downstream nodes supported only by it, according to the user's selected mode.", "The user deleted the running worker. This call was cancelled. After the worker leaves the write section, soft deletion marks the intent deleted and retains outputs; hard deletion removes it and downstream nodes supported only by it, according to the user's selected mode.")
	Register("Worker finished normally", "Worker finished normally")
	Register("The worker finished normally and detachWork released its context resources. This is not an interruption; seeing it in an interruption message indicates a race between cancellation and completion events.", "The worker finished normally and detachWork released its context resources. This is not an interruption; seeing it in an interruption message indicates a race between cancellation and completion events.")
	Register("New run blocked while paused", "New run blocked while paused")
	Register("The engine refused a new execution context while the task was paused, preventing a claim/pause race from starting a worker. Claimed intents return to frontier.", "The engine refused a new execution context while the task was paused, preventing a claim/pause race from starting a worker. Claimed intents return to frontier.")
	Register("User stopped this conversation turn", "User stopped this conversation turn")
	Register("The user clicked Stop to cancel this main-agent or conversation-agent turn. Existing activity records remain; another message can be sent.", "The user clicked Stop to cancel this main-agent or conversation-agent turn. Existing activity records remain; another message can be sent.")
	Register("Task pause stopped main-agent chat", "Task pause stopped main-agent chat")
	Register("Pausing the task also cancelled its active main-agent conversation. Existing activity records remain; resuming the task does not replay this message automatically.", "Pausing the task also cancelled its active main-agent conversation. Existing activity records remain; resuming the task does not replay this message automatically.")
	Register("Conversation finished normally", "Conversation finished normally")
	Register("The conversation turn finished normally and the server released its context resources. This is not an interruption; seeing it in an interruption message indicates a cancellation/completion race.", "The conversation turn finished normally and the server released its context resources. This is not an interruption; seeing it in an interruption message indicates a cancellation/completion race.")
	Register("Backend process is shutting down", "Backend process is shutting down")
	Register("The backend received SIGINT or SIGTERM and is restarting, updating, or shutting down. Active agents are cancelled; leftover running intents reset to open and execute again after restart.", "The backend received SIGINT or SIGTERM and is restarting, updating, or shutting down. Active agents are cancelled; leftover running intents reset to open and execute again after restart.")
	Register("Per-run hard timeout backstop triggered", "Per-run hard timeout backstop triggered")
	Register("This run exceeded its soft wall-clock budget and grace period. A model request or tool likely failed to return, preventing normal turn-boundary wrap-up. Inspect the last unfinished tool call before interruption.", "This run exceeded its soft wall-clock budget and grace period. A model request or tool likely failed to return, preventing normal turn-boundary wrap-up. Inspect the last unfinished tool call before interruption.")
	Register("Parent context reached its deadline", "Parent context reached its deadline")
	Register("Parent context reached its deadline without a named WithTimeoutCause reason: ", "Parent context reached its deadline without a named WithTimeoutCause reason: ")
	Register("Canceller did not attach a named cause", "Canceller did not attach a named cause")
	Register("Parent context was cancelled without a named context.WithCancelCause reason. Register the cause in agent/cancelcause.go and attach it at the cancellation site.", "Parent context was cancelled without a named context.WithCancelCause reason. Register the cause in agent/cancelcause.go and attach it at the cancellation site.")
	Register("The model ended the round normally without a text summary; use this round's tool records for facts and assets", "The model ended the round normally without a text summary; use this round's tool records for facts and assets")
	Register("MaxTurns reached: the SDK performed wrap-up and saved facts/assets. The intent becomes exhausted so the planner can continue with another direction; this is not treated as failure", "MaxTurns reached: the SDK performed wrap-up and saved facts/assets. The intent becomes exhausted so the planner can continue with another direction; this is not treated as failure")
	Register("MaxDuration reached: running tools are interrupted for immediate wrap-up and identified facts/assets are saved. The intent becomes exhausted", "MaxDuration reached: running tools are interrupted for immediate wrap-up and identified facts/assets are saved. The intent becomes exhausted")
	Register("Model/API failure (network, authentication, rate limit, provider 5xx, etc.). After retries the intent becomes blocked; little exploration may have occurred. Inspect get_worker_trace before deciding to retry or change approach", "Model/API failure (network, authentication, rate limit, provider 5xx, etc.). After retries the intent becomes blocked; little exploration may have occurred. Inspect get_worker_trace before deciding to retry or change approach")
	Register("Context reached its hard limit and the request was blocked before sending; narrow the intent or reduce tool output", "Context reached its hard limit and the request was blocked before sending; narrow the intent or reduce tool output")
	Register("Prompt too long and compaction retries exhausted; execution cannot continue", "Prompt too long and compaction retries exhausted; execution cannot continue")
	Register("The model does not support this round's multimodal content; use a vision-capable model or avoid image tool output", "The model does not support this round's multimodal content; use a vision-capable model or avoid image tool output")
	Register("A Stop hook prevented completion and execution could not resume; check whether task Guard rules are too restrictive", "A Stop hook prevented completion and execution could not resume; check whether task Guard rules are too restrictive")
	Register("A tool or hook stopped execution, for example for an out-of-scope target or disabled command; inspect the last tool_result interception explanation", "A tool or hook stopped execution, for example for an out-of-scope target or disabled command; inspect the last tool_result interception explanation")
	Register("Run cancelled while the model was streaming output", "Run cancelled while the model was streaming output")
	Register("Run cancelled during tool execution", "Run cancelled during tool execution")
	Register("Cancellation cause unavailable", "Cancellation cause unavailable")
	Register("execution", "execution")
	Register("model output", "model output")
	Register("tool execution", "tool execution")
	Register("(Run interrupted: ", "(Run interrupted: ")
	Register("; stopped during ", "; stopped during ")
	Register("; incomplete)", "; incomplete)")
	Register("(Run budget limit reached (", "(Run budget limit reached (")
	Register("); facts saved during wrap-up", "); facts saved during wrap-up")
	Register("; no text summary)", "; no text summary)")
	Register("(No text summary; terminal state ", "(No text summary; terminal state ")
	Register("- **Terminal state**: `%s` - %s\n", "- **Terminal state**: `%s` - %s\n")
	Register("- **Interruption cause** (`%s`): %s\n", "- **Interruption cause** (`%s`): %s\n")
	Register("- **Interruption cause**: unavailable; the canceller may not have attached a named cause through context.WithCancelCause\n", "- **Interruption cause**: unavailable; the canceller may not have attached a named cause through context.WithCancelCause\n")
	Register("- **Underlying error**: `%v`\n", "- **Underlying error**: `%v`\n")
	Register("- **Partial output generated before cancellation**:\n\n", "- **Partial output generated before cancellation**:\n\n")
	Register("- **Executed**: %d model turns\n", "- **Executed**: %d model turns\n")
	Register("- **Run duration**: %s\n", "- **Run duration**: %s\n")
	Register("- **Total tokens**: input %d / output %d / cache read %d / cache write %d\n", "- **Total tokens**: input %d / output %d / cache read %d / cache write %d\n")
	Register("- **Tool calls**: run ended before any tool was called\n", "- **Tool calls**: run ended before any tool was called\n")
	Register("- **Tool running at interruption**: `%s` (running for %s, **no result returned**)\n\n  ```json\n  %s\n  ```\n", "- **Tool running at interruption**: `%s` (running for %s, **no result returned**)\n\n  ```json\n  %s\n  ```\n")
	Register("- **Last tool before interruption**: `%s` (returned normally)\n", "- **Last tool before interruption**: `%s` (returned normally)\n")
	Register("Run context was cancelled without an underlying Terminal event", "Run context was cancelled without an underlying Terminal event")
	Register("Unknown terminal state; harness may have added a TerminalReason. Update reasonHint", "Unknown terminal state; harness may have added a TerminalReason. Update reasonHint")
	Register("%d turns", "%d turns")
	Register(", elapsed ", ", elapsed ")
}
